import 'dart:convert';import 'dart:io';import 'dart:typed_data';import 'package:crypto/crypto.dart';import 'package:http/http.dart' as http;import 'package:path/path.dart' as p;import 'package:path_provider/path_provider.dart';
class ContentUpdateException implements Exception{ContentUpdateException(this.message);final String message;@override String toString()=>message;}
class ContentUpdateResult{const ContentUpdateResult({required this.version,required this.files,required this.updatedAt});final String version;final List<String> files;final DateTime updatedAt;}
class ContentUpdateService{
 ContentUpdateService({http.Client? client}):_client=client??http.Client();final http.Client _client;static const maxManifestBytes=256*1024,maxFileBytes=1024*1024,maxTotalBytes=8*1024*1024;
 Future<ContentUpdateResult> checkAndDownload(Uri manifestUri)async{
  if(manifestUri.scheme!='https'||manifestUri.host!='raw.githubusercontent.com'||manifestUri.pathSegments.length<4)throw ContentUpdateException('Only HTTPS raw.githubusercontent.com content manifests are accepted.');
  final response=await _client.get(manifestUri).timeout(const Duration(seconds:15));if(response.statusCode!=200)throw ContentUpdateException('Content source returned HTTP ${response.statusCode}.');if(response.bodyBytes.length>maxManifestBytes)throw ContentUpdateException('Manifest is too large.');
  final dynamic decoded;try{decoded=jsonDecode(utf8.decode(response.bodyBytes));}catch(_){throw ContentUpdateException('Manifest JSON is invalid.');}
  if(decoded is! Map||decoded['schema_version']!=1||decoded['content_version'] is! String||decoded['files'] is! List)throw ContentUpdateException('Manifest schema is not supported.');
  final files=decoded['files'] as List;if(files.length>80)throw ContentUpdateException('Manifest contains too many files.');
  final root=manifestUri.replace(path:manifestUri.path.substring(0,manifestUri.path.lastIndexOf('/')+1),query:null,fragment:null);final downloads=<String,Uint8List>{};var total=0;
  for(final raw in files){if(raw is! Map)throw ContentUpdateException('Invalid file entry.');final path=raw['path'];final hash=raw['sha256'];final size=raw['size_bytes'];if(path is! String||!RegExp(r'^(categories|articles|breeds|training|safety)/[A-Za-z0-9._/-]+\.json$').hasMatch(path)||path.contains('..')||hash is! String||!RegExp(r'^[a-fA-F0-9]{64}$').hasMatch(hash)||size is! int||size<1||size>maxFileBytes)throw ContentUpdateException('A manifest file entry failed validation.');
   final uri=root.resolve(path);if(uri.host!=manifestUri.host||uri.scheme!='https')throw ContentUpdateException('Unexpected content host.');final fileResponse=await _client.get(uri).timeout(const Duration(seconds:15));if(fileResponse.statusCode!=200||fileResponse.bodyBytes.length!=size)throw ContentUpdateException('Content file size or status mismatch: $path');if(sha256.convert(fileResponse.bodyBytes).toString().toLowerCase()!=hash.toLowerCase())throw ContentUpdateException('Checksum mismatch: $path');total+=size;if(total>maxTotalBytes)throw ContentUpdateException('Content pack exceeds the size budget.');downloads[path]=fileResponse.bodyBytes;
  }
  final appDir=await getApplicationSupportDirectory();final cacheRoot=Directory(p.join(appDir.path,'pawpal','content'));await cacheRoot.create(recursive:true);final version=(decoded['content_version'] as String).replaceAll(RegExp(r'[^A-Za-z0-9._-]'),'_');final staging=Directory(p.join(cacheRoot.path,'$version.tmp'));if(await staging.exists())await staging.delete(recursive:true);await staging.create(recursive:true);
  try{for(final entry in downloads.entries){final target=File(p.join(staging.path,entry.key));await target.parent.create(recursive:true);await target.writeAsBytes(entry.value,flush:true);}final finalDir=Directory(p.join(cacheRoot.path,version));if(await finalDir.exists())await finalDir.delete(recursive:true);await staging.rename(finalDir.path);final pointer=File(p.join(cacheRoot.path,'active.txt'));final tmp=File('${pointer.path}.tmp');await tmp.writeAsString(version,flush:true);if(await pointer.exists())await pointer.delete();await tmp.rename(pointer.path);}catch(_){if(await staging.exists())await staging.delete(recursive:true);rethrow;}
  return ContentUpdateResult(version:version,files:downloads.keys.toList(),updatedAt:DateTime.now());
